public class SonarEntityIDFilter extends SonarFilter<SonarEntityIDFilter>{ public static final MapCodec<SonarEntityIDFilter> CODEC=RecordCodecBuilder.mapCodec(i->baseCodec(i).and(Codec.STRING.fieldOf("entity_id").forGetter(SonarEntityIDFilter::getEntityID)).apply(i,SonarEntityIDFilter::new)); public static final StreamCodec<RegistryFriendlyByteBuf,SonarEntityIDFilter> STREAM_CODEC=StreamCodec.composite(baseStreamCodec(SonarEntityIDFilter::new),Function.identity(),ByteBufCodecs.STRING_UTF8,SonarEntityIDFilter::getEntityID,(f,id)->{f.entityID=id;return f;}); private String entityID=""; public SonarEntityIDFilter(){} private SonarEntityIDFilter(boolean e,String id){super(e);entityID=id;} public SonarEntityIDFilter(SonarEntityIDFilter o){super(o);entityID=o.entityID;} public boolean canFilter(BlockState s){return false;} public boolean canFilter(Entity e){ResourceLocation n=BuiltInRegistries.ENTITY_TYPE.getKey(e.getType()); return n!=null&&!entityID.isEmpty()&&WildcardMatcher.matches(entityID,n.toString());} public SonarFilterType getType(){return SonarFilterType.ENTITY_ID;} public SonarEntityIDFilter clone(){return new SonarEntityIDFilter(this);} public boolean hasFilter(){return !entityID.isEmpty();} public String getEntityID(){return entityID;} public void setEntityID(String s){entityID=s;} public int hashCode(){return 31*super.hashCode()+entityID.hashCode();} public boolean equals(Object o){return this==o||(super.equals(o)&&entityID.equals(((SonarEntityIDFilter)o).entityID));}}